"""Filter expression module for vector store metadata filtering."""

from __future__ import annotations

from enum import Enum
from typing import Annotated, Any, Literal, Union

from pydantic import BaseModel, Field


class Operator(str, Enum):
    """Enum of comparison operators supported by filter conditions."""

    eq = "eq"
    ne = "ne"
    gt = "gt"
    gte = "gte"
    lt = "lt"
    lte = "lte"
    in_ = "in"


class FilterExpr(BaseModel):
    """Abstract base class for all filter expressions.

    Supports the ``&`` (AndExpr), ``|`` (OrExpr) and ``~`` (NotExpr) operator
    overloads for building composite expressions fluently.
    """

    def evaluate(self, record: dict) -> bool:
        """Evaluate this expression against a record."""
        raise NotImplementedError

    def __and__(self, other: "FilterExpr") -> "AndExpr":
        """Combine two expressions with a logical AND, flattening AndExprs."""
        left = self.and_ if isinstance(self, AndExpr) else [self]
        right = other.and_ if isinstance(other, AndExpr) else [other]
        return AndExpr(and_=[*left, *right])

    def __or__(self, other: "FilterExpr") -> "OrExpr":
        """Combine two expressions with a logical OR, flattening OrExprs."""
        left = self.or_ if isinstance(self, OrExpr) else [self]
        right = other.or_ if isinstance(other, OrExpr) else [other]
        return OrExpr(or_=[*left, *right])

    def __invert__(self) -> "FilterExpr":
        """Negate this expression, cancelling double-negation."""
        if isinstance(self, NotExpr):
            return self.not_
        return NotExpr(not_=self)


class Condition(FilterExpr):
    """A single field comparison condition."""

    type: Literal["condition"] = "condition"
    field: str
    operator: Operator
    value: Any = None

    def __init__(
        self,
        field: str | None = None,
        operator: Operator | None = None,
        value: Any = None,
        **data: Any,
    ):
        # Support both positional (field, operator, value) and keyword construction.
        if field is not None:
            data["field"] = field
        if operator is not None:
            data["operator"] = operator
        if "value" not in data:
            data["value"] = value
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Apply the operator comparison; return False if the field is absent."""
        if self.field not in record:
            return False
        actual = record[self.field]
        match self.operator:
            case Operator.eq:
                return actual == self.value
            case Operator.ne:
                return actual != self.value
            case Operator.gt:
                return actual > self.value
            case Operator.gte:
                return actual >= self.value
            case Operator.lt:
                return actual < self.value
            case Operator.lte:
                return actual <= self.value
            case Operator.in_:
                return actual in self.value
        return False


class AndExpr(FilterExpr):
    """Logical AND of a list of filter expressions."""

    type: Literal["and"] = "and"
    and_: list["FilterExprType"]

    def __init__(self, and_: list["FilterExpr"] | None = None, **data: Any):
        if and_ is not None:
            data["and_"] = and_
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Return True only if all sub-expressions evaluate to True."""
        return all(expr.evaluate(record) for expr in self.and_)


class OrExpr(FilterExpr):
    """Logical OR of a list of filter expressions."""

    type: Literal["or"] = "or"
    or_: list["FilterExprType"]

    def __init__(self, or_: list["FilterExpr"] | None = None, **data: Any):
        if or_ is not None:
            data["or_"] = or_
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Return True if at least one sub-expression evaluates to True."""
        return any(expr.evaluate(record) for expr in self.or_)


class NotExpr(FilterExpr):
    """Logical NOT of a single filter expression."""

    type: Literal["not"] = "not"
    not_: "FilterExprType"

    def __init__(self, not_: "FilterExpr" | None = None, **data: Any):
        if not_ is not None:
            data["not_"] = not_
        super().__init__(**data)

    def evaluate(self, record: dict) -> bool:
        """Return the negation of the inner expression."""
        return not self.not_.evaluate(record)


# Discriminated union of all concrete filter expressions. This allows nested
# expressions to be serialized and deserialized to/from the correct subclass.
FilterExprType = Annotated[
    Union[Condition, AndExpr, OrExpr, NotExpr],
    Field(discriminator="type"),
]

AndExpr.model_rebuild()
OrExpr.model_rebuild()
NotExpr.model_rebuild()


class _FieldProxy:
    """A proxy for a single field that produces Condition objects."""

    def __init__(self, name: str):
        self._name = name

    def __eq__(self, other: Any) -> Condition:  # type: ignore[override]
        return Condition(field=self._name, operator=Operator.eq, value=other)

    def __ne__(self, other: Any) -> Condition:  # type: ignore[override]
        return Condition(field=self._name, operator=Operator.ne, value=other)

    def __gt__(self, other: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.gt, value=other)

    def __ge__(self, other: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.gte, value=other)

    def __lt__(self, other: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.lt, value=other)

    def __le__(self, other: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.lte, value=other)

    def in_(self, values: list) -> Condition:
        return Condition(field=self._name, operator=Operator.in_, value=list(values))

    __hash__ = None  # type: ignore[assignment]


class _FBuilder:
    """Fluent builder for constructing filter conditions via attribute access."""

    def __getattr__(self, name: str) -> _FieldProxy:
        if name.startswith("__") and name.endswith("__"):
            raise AttributeError(name)
        return _FieldProxy(name)


